link.script:
tailwind.config = {
theme: {
extend: {
colors: {
'primary-dark': '#1A2D40', // Bleu Nuit
'accent-gold': '#D4AF37',   // Doré
'accent-light-gold': '#F3D8B0', // Lighter Doré for gradients/secondary elements
'neutral-dark': '#000000',  // Pure Black for text
'neutral-light': '#F8F9FA', // Background white/light gray
'success-green': '#4CAF50', // Standard green for positive feedback
'error-red': '#EF4444',     // Standard red for errors
}
}
}
}

body.script:
// Initialize AOS
AOS.init({
duration: 1200,
once: true,
offset: 100
});

// Initialize Feather Icons
feather.replace();

// Vanta.js initialization
let vantaEffect;
if (typeof VANTA !== 'undefined') {
vantaEffect = VANTA.GLOBE({
el: "#vanta-bg",
mouseControls: true,
touchControls: true,
gyroControls: false,
minHeight: 200.00,
minWidth: 200.00,
scale: 1.00,
scaleMobile: 1.00,
color: 0x1A2D40, // primary-dark
color2: 0xD4AF37, // accent-gold
backgroundColor: 0x1A2D40, // primary-dark
});
}

// Create particles
function createParticles() {
const particlesContainer = document.getElementById('particles');
if (!particlesContainer) return;

for (let i = 0; i < 20; i++) {
const particle = document.createElement('div');
particle.className = 'particle';
particle.style.width = Math.random() * 5 + 2 + 'px';
particle.style.height = particle.style.width;
particle.style.left = Math.random() * 100 + '%';
particle.style.animationDelay = Math.random() * 20 + 's';
particle.style.animationDuration = (Math.random() * 10 + 15) + 's';
particlesContainer.appendChild(particle);
}
}
createParticles();

// Navbar scroll effect
let lastScroll = 0;
const navbar = document.getElementById('navbar');
window.addEventListener('scroll', () => {
const currentScroll = window.pageYOffset;
if (currentScroll > 100) {
navbar.classList.add('scrolled');
} else {
navbar.classList.remove('scrolled');
}
lastScroll = currentScroll;
});

// Mobile menu toggle
const mobileMenuButton = document.getElementById('mobile-menu-button');
const closeMenuButton = document.getElementById('close-menu-button');
const mobileMenu = document.getElementById('mobile-menu');

function openMobileMenu() {
mobileMenu.classList.remove('-translate-x-full');
document.body.style.overflow = 'hidden';
}

function closeMobileMenu() {
mobileMenu.classList.add('-translate-x-full');
document.body.style.overflow = '';
}

mobileMenuButton.addEventListener('click', openMobileMenu);
closeMenuButton.addEventListener('click', closeMobileMenu);

// Back to top button
const backToTop = document.getElementById('back-to-top');
window.addEventListener('scroll', () => {
if (window.pageYOffset > 300) {
backToTop.classList.add('visible');
} else {
backToTop.classList.remove('visible');
}
});

backToTop.addEventListener('click', () => {
window.scrollTo({ top: 0, behavior: 'smooth' });
});


// FAQ accordion
document.querySelectorAll('.faq-item').forEach(item => {
item.addEventListener('click', () => {
const isActive = item.classList.contains('active');
document.querySelectorAll('.faq-item').forEach(i => {
i.classList.remove('active');
const icon = i.querySelector('i[data-feather="chevron-down"]');
if (icon) {
icon.style.transform = 'rotate(0deg)';
}
});
if (!isActive) {
item.classList.add('active');
const icon = item.querySelector('i[data-feather="chevron-down"]');
if (icon) {
icon.style.transform = 'rotate(180deg)';
}
}
feather.replace();
});
});

// Form submission
const quoteForm = document.getElementById('quote-form');
if (quoteForm) {
quoteForm.addEventListener('submit', (e) => {
e.preventDefault();
const submitText = document.getElementById('submit-text');
const originalText = submitText.textContent;
submitText.textContent = 'Envoi en cours...';

// Simulate form submission
setTimeout(() => {
submitText.textContent = 'Demande envoyée !';
quoteForm.reset();
setTimeout(() => {
submitText.textContent = originalText;
}, 3000);
}, 1500);
});
}

// Smooth scroll for anchor links
document.querySelectorAll('a[href^="#"]').forEach(anchor => {
anchor.addEventListener('click', function (e) {
e.preventDefault();
const target = document.querySelector(this.getAttribute('href'));
if (target) {
target.scrollIntoView({
behavior: 'smooth',
block: 'start'
});
}
});
});

// Refresh feather icons on dynamic content
setInterval(() => {
feather.replace();
}, 1000);
